    if "age" in payload and not isinstance(payload["age"], (int, float)):
        return "age must be a number"
    if "tags" in payload and not isinstance(payload["tags"], list):
        return "tags must be a list"
    if "email" in payload and not isinstance(payload["email"], str):
        return "email must be a string"
    if "active" in payload and not isinstance(payload["active"], bool):
        return "active must be a bool"
    return True

